  const centre = Math.hypot(relB(sx - NB / 2), sy - (SHORE_S + SHORE_N) / 2), shore = sy < SHORE_N + 4 || sy > SHORE_S - 4;
  if (centre < 4.5) { seed[2] = 'downtown'; continue; }
