      if (fz < 0.3 && (fe < 0.37 || fe > 0.63)) return set(i, '|', C(GRAY, L)); // railing posts
      const t = (fe - 0.35) / 0.3, up = fl & 1 ? t : 1 - t; // the ladder runs the other way on each floor
      if (Math.abs(fz - up) < 0.07) return set(i, fl & 1 ? '/' : '\\', C(GRAY, L));
