  duck: pad(['  _', '<(o)__', ' (___/']),
  tortoise: pad(['  ____', ' /####\\_', '/_/  \\_\\o']),
  bear: pad(['   _    _', '  ( `--` )___', ' (  -  -     )', '  `----^-----`']),
