  for (const f of flamingos) art(f.gx, f.gy, 0, 0.04, 0.13, Math.sin(T * 0.4 + f.k * 2) > 0.85 ? ANIMAL_ART.flamingo.map(l => l.replace('o>', 'o_')) : ANIMAL_ART.flamingo, (c, row, L) => row === 1 && c === '>' ? C(ORANGE, L) : C(MAG, Math.max(L, 6)));
